(function(){
 'use strict';
 const C=Torneo, $=id=>document.getElementById(id), H=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const params=new URLSearchParams(location.search), admin=params.get('administrar')==='1';
 let tournament=null,sha=null,dirty=false,busy=false,divisionId=params.get('division')??'',view=params.get('vista')??'resumen',pendingImages={},previewImages={},catalog=[],preview=null,formCallback=null,formDirty=false,formApplied=false;
 const store=createTournamentStorage({getToken:()=>localStorage.getItem('lmbc_gh_token')??'',core:C});
 const app=$('tor-app'),dialog=$('tor-dialog'),form=$('tor-form');
 const tabs={resumen:'Resumen',equipos:'Equipos y rosters',grupos:'Grupos y standing',rol:'Agregar Juego / Rol',captura:'Capturar resultados',llaves:'Llaves',lideres:'Líderes y rankings',comparar:'Comparar equipos',config:'Configuración'};
 const notify=(s,error=false)=>{$('tor-message').textContent=s;$('tor-message').className=error?'error':'';};
 const action=(a,label,id='',cls='')=>`<button type="button" data-action="${a}" data-id="${H(id)}" class="${cls}">${label}</button>`;
 const options=(list,value='')=>list.map(x=>`<option value="${H(x.id)}" ${x.id===value?'selected':''}>${H(x.name)}</option>`).join('');
 const field=(label,key,value='',type='text',extra='')=>`<label>${H(label)}<input name="${key}" type="${type}" value="${H(value)}" ${extra}></label>`;
 const select=(label,key,list,value='',extra='')=>`<label>${H(label)}<select name="${key}" ${extra}>${options(list,value)}</select></label>`;
 const imageInput=()=>'<label>Logo (PNG, JPG o WebP, hasta 10 MB)<input type="file" name="logoFile" accept="image/png,image/jpeg,image/webp"></label>';
 const logo=path=>path?(pendingImages[path]||previewImages[path]?'data:image/png;base64,'+(pendingImages[path]||previewImages[path]):'../'+path):'../img/equipos/placeholder.svg';
 const entryName=id=>C.teamName(tournament,id);
 const div=()=>tournament.divisions.find(d=>d.id===divisionId);
 const editable=()=>{if(!admin)throw new Error('Abre Administrar torneos para hacer cambios.');if(busy)throw new Error('Espera a que termine el guardado.');};
 function draft(){if(!tournament||!admin)return;try{localStorage.setItem('lmbc_tor_draft_'+tournament.id,JSON.stringify({data:tournament,sha,images:pendingImages,at:new Date().toISOString()}));}catch{notify('El borrador sigue abierto, pero no cabe en el navegador. Guarda o exporta una copia antes de cerrar.',true);}}
 function commit(next,label){editable();C.validate(next);next.history=[...(next.history??[]),{at:new Date().toISOString(),action:label}].slice(-150);tournament=next;dirty=true;draft();render();notify(label+'. Pendiente de guardar en el torneo.');}
 function address(){const q=new URLSearchParams();if(admin)q.set('administrar','1');if(tournament)q.set('id',tournament.id);if(divisionId)q.set('division',divisionId);q.set('vista',view);history.replaceState(null,'','?'+q);}
 function restoreForm(){try{const saved=JSON.parse(localStorage.getItem('lmbc_tor_form')??'null');if(saved?.tournament===tournament?.id&&saved.title===$('tor-fields').querySelector('h2')?.textContent&&confirm('Hay datos pendientes de este formulario. ¿Recuperarlos?')){for(const item of saved.values){const el=form.elements.namedItem(item.name);if(el&&el.type!=='file'){if(el.type==='checkbox')el.checked=item.checked;else el.value=item.value;}}formDirty=true;}}catch{}}
 function modal(title,body,callback,readOnly=false){form.reset();$('tor-fields').innerHTML='<h2>'+H(title)+'</h2>'+body;$('tor-form-error').textContent='';form.querySelector('[type=submit]').hidden=readOnly;$('tor-cancel').textContent=readOnly?'Cerrar':'Cancelar';formCallback=callback;formDirty=false;formApplied=false;dialog.showModal();if(!readOnly)restoreForm();}
 form.addEventListener('input',()=>{formDirty=true;try{localStorage.setItem('lmbc_tor_form',JSON.stringify({tournament:tournament?.id,title:$('tor-fields').querySelector('h2').textContent,values:Array.from(form.elements).filter(e=>e.name&&e.type!=='file').map(e=>({name:e.name,value:e.value,checked:e.checked}))}));}catch{}});
 form.addEventListener('submit',async e=>{e.preventDefault();const values=new FormData(form);const controls=Array.from(form.querySelectorAll('input,select,textarea,button'));controls.forEach(e=>e.disabled=true);try{if(!formApplied){await formCallback(values);formApplied=true;}if(dirty&&storeToken())await save();formDirty=false;localStorage.removeItem('lmbc_tor_form');dialog.close();}catch(err){$('tor-form-error').textContent=err.message;}finally{controls.forEach(e=>e.disabled=false);}});
 form.addEventListener('input',()=>{formApplied=false;});
 function closeForm(){if(formDirty&&!confirm('¿Descartar los cambios de este formulario?'))return;formDirty=false;localStorage.removeItem('lmbc_tor_form');dialog.close();}
 $('tor-cancel').onclick=closeForm;dialog.addEventListener('cancel',e=>{e.preventDefault();closeForm();});
 window.addEventListener('beforeunload',e=>{if(dirty||formDirty||busy){e.preventDefault();e.returnValue='';}});
 async function prepareLogo(file,tid){if(!file?.size)return null;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024)throw new Error('Elige PNG, JPG o WebP de hasta 10 MB.');const url=URL.createObjectURL(file);try{const img=new Image();await new Promise((ok,no)=>{img.onload=ok;img.onerror=()=>no(new Error('No se pudo abrir la imagen.'));img.src=url;});const scale=Math.min(1,512/Math.max(img.naturalWidth,img.naturalHeight));const cv=document.createElement('canvas');cv.width=Math.max(1,Math.round(img.naturalWidth*scale));cv.height=Math.max(1,Math.round(img.naturalHeight*scale));cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height);return {path:'img/torneos/'+tid+'/'+C.id('logo')+'.png',data:cv.toDataURL('image/png').split(',')[1]};}finally{URL.revokeObjectURL(url);}}
 function keepLogo(prepared,obj){if(prepared){pendingImages[prepared.path]=prepared.data;obj.logo=prepared.path;}}
 function exportJSON(){const blob=new Blob([JSON.stringify(tournament,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=tournament.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 async function open(id){if(dirty&&!confirm('Hay cambios pendientes. ¿Descartarlos y abrir otro torneo?'))return;const file=await store.load(id,admin&&!!storeToken());tournament=file.data;sha=file.sha;dirty=false;pendingImages={};preview=null;
  if(admin){try{const draftFile=JSON.parse(localStorage.getItem('lmbc_tor_draft_'+id)??'null');if(draftFile&&confirm('Hay un borrador local pendiente. ¿Recuperarlo?')){tournament=draftFile.data;sha=draftFile.sha;pendingImages=draftFile.images??{};dirty=true;}}catch{}}
  divisionId=tournament.divisions.some(d=>d.id===divisionId)?divisionId:tournament.divisions[0]?.id??'';render();}
 const storeToken=()=>localStorage.getItem('lmbc_gh_token')??'';
 async function refresh(){catalog=(await store.catalog(admin&&!!storeToken())).torneos;renderCatalog();}
 function renderCatalog(){tournament=null;dirty=false;app.innerHTML=`<h1>Torneos relámpago</h1><p>Cada torneo tiene sus categorías, grupos, equipos y estadísticas.</p>${admin?'<div class="tor-actions">'+action('new','Crear torneo')+action('drafts','Recuperar borrador','','secondary')+'</div>':'<p><a href="?administrar=1">Administrar torneos</a></p>'}<div class="tor-grid">${catalog.filter(t=>admin||['publicado','finalizado'].includes(t.status)).map(t=>`<article class="tor-card"><img src="${H(logo(t.logo))}" alt="Logo de ${H(t.name)}"><h2>${H(t.name)}</h2><p>${H(t.start||'Fecha por definir')} ${t.end?'— '+H(t.end):''}</p><p>${H(t.status)} · ${t.divisions.length} categorías / ramas</p>${action('open','Abrir torneo',t.id)}</article>`).join('')||'<p class="tor-empty">Todavía no hay torneos publicados.</p>'}</div>`;}
 async function save(){editable();busy=true;render();notify('Guardando torneo, catálogo y logos…');try{const used=new Set([tournament.logo,...tournament.teams.map(x=>x.logo)]);const images=Object.fromEntries(Object.entries(pendingImages).filter(([p])=>used.has(p)));const saved=await store.save(tournament,sha,images);sha=saved.sha;Object.assign(previewImages,images);pendingImages={};dirty=false;localStorage.removeItem('lmbc_tor_draft_'+tournament.id);notify('Torneo guardado. Los cambios públicos aparecerán al terminar la publicación del sitio.');}finally{busy=false;render();}}
 function render(){if(!tournament)return;const t=tournament;if(!t.divisions.some(d=>d.id===divisionId))divisionId=t.divisions[0]?.id??'';address();app.innerHTML=`<div class="tor-actions">${action('catalog','← Todos los torneos','','secondary')}${action('print','Imprimir / PDF','','secondary')}${admin?action('export','Exportar datos','','secondary'):`<a class="tor-link" href="?administrar=1&id=${H(t.id)}">Administrar este torneo</a>`}</div><h1>${H(t.name)}</h1><p><span class="tor-tag">${H(t.status)}</span> ${H(t.start)} ${t.end?'— '+H(t.end):''}</p>${admin?`<div class="tor-savebar tor-actions"><strong>${dirty?'Cambios pendientes':'Sin cambios pendientes'}</strong><button data-action="save" ${busy?'disabled':''}>${busy?'Guardando…':'Guardar cambios del torneo'}</button>${action('reload','Abrir versión guardada','','secondary')}</div>`:''}<div class="tor-context">${select('Categoría y rama','division',t.divisions.map(d=>({id:d.id,name:d.name+' · '+d.branch})),divisionId,'id="tor-division"')}<span>Equipos, grupos y estadísticas pertenecen exclusivamente a esta división del torneo.</span></div><nav class="tor-tabs" aria-label="Secciones del torneo">${Object.entries(tabs).filter(([k])=>admin||!['captura','config'].includes(k)).map(([k,n])=>action('tab',n,k,k===view?'active':'secondary')).join('')}</nav><section id="tor-content"></section>`;
  if(!admin&&['captura','config'].includes(view))view='resumen';const views={resumen:renderSummary,equipos:renderTeams,grupos:renderGroups,rol:()=>renderGames(false),captura:()=>renderGames(true),llaves:renderBracket,lideres:renderLeaders,comparar:renderCompare,config:renderSettings};$('tor-content').innerHTML=(views[view]??renderSummary)();if(busy)app.querySelectorAll('button,input,select').forEach(b=>b.disabled=true);
 }
 function renderSummary(){const t=tournament,d=div(),games=t.games.filter(g=>g.divisionId===divisionId&&!g.bye),entries=C.divisionEntries(t,divisionId),final=t.games.filter(g=>g.divisionId===divisionId&&g.phase==='knockout').sort((a,b)=>b.round-a.round)[0];return `<h2>Resumen ${d?H(d.name+' · '+d.branch):''}</h2>${!d?'<p>Crea las categorías y ramas en Configuración para comenzar.</p>':''}<div class="tor-grid"><div class="tor-card"><h3>${entries.length} equipos</h3><p>${entries.reduce((n,e)=>n+e.roster.filter(p=>p.active!==false).length,0)} jugadores inscritos</p></div><div class="tor-card"><h3>${games.length} partidos</h3><p>${games.filter(g=>g.status==='jugado').length} terminados · ${games.filter(g=>g.status==='programado').length} pendientes</p></div><div class="tor-card"><h3>${d?.groups.length??0} grupos</h3><p>${d?.qualify??2} clasificados por grupo</p></div></div>${final&&C.winner(final)?`<div class="tor-card"><h2>🏆 Campeón: ${H(entryName(C.winner(final)))}</h2><p>Subcampeón: ${H(entryName(final.home===C.winner(final)?final.away:final.home))}</p></div>`:''}${admin?'<p class="tor-help">Empieza en Configuración para nombrar las categorías y ramas; después inscribe equipos, organiza grupos y genera el rol. Con el token conectado, los formularios guardan al confirmar. Si falla la conexión, queda un borrador recuperable y puedes reintentar con Guardar cambios del torneo.</p>':''}`;}
 function renderTeams(){if(!div())return '<p>Crea una categoría y rama primero.</p>';const t=tournament;return `<h2>Equipos y rosters</h2>${admin?`<div class="tor-actions">${action('team-new','Crear equipo con logo')}${action('entry-new','Inscribir equipo en esta categoría')}${action('import','Copiar desde la liga','','secondary')}</div>`:''}<p>Un equipo puede participar en varias categorías. Cada inscripción tiene su propio roster.</p><div class="tor-grid">${C.divisionEntries(t,divisionId).map(e=>{const team=t.teams.find(x=>x.id===e.teamId);return `<article class="tor-card"><img src="${H(logo(team.logo))}" alt="Logo de ${H(team.name)}"><h3>${H(team.name)}</h3><p>${H(div().groups.find(g=>g.id===e.groupId)?.name??'Sin grupo')} · ${e.roster.filter(p=>p.active!==false).length} jugadores</p><div class="tor-actions">${action('roster','Ver roster y estadísticas',e.id,'secondary')}${admin?action('team-edit','Nombre / logo',team.id,'secondary')+action('entry-delete','Retirar inscripción',e.id,'danger'):''}</div></article>`;}).join('')||'<p class="tor-empty">Inscribe el primer equipo en esta categoría y rama.</p>'}</div>`;}
 function renderGroups(){const d=div();if(!d)return '<p>Crea una categoría y rama primero.</p>';return `<h2>Grupos y standing</h2>${admin?`<div class="tor-actions">${action('groups','Organizar grupos')}${action('ties','Resolver empate exacto','','secondary')}</div>`:''}<p>${d.win} puntos por victoria · ${d.loss} por derrota · ${d.forfeit} por forfeit. Clasifican ${d.qualify} por grupo.</p><p class="tor-muted">Desempates: puntos entre empatados, diferencial entre empatados, diferencial general y puntos a favor. Un empate exacto requiere resolución del organizador. Posiciones provisionales hasta completar el grupo.</p>${d.groups.map(g=>{const rows=C.standings(tournament,d.id,g.id);return `<div class="tor-card"><h3>${H(g.name)}</h3><div class="tor-scroll"><table class="tor-table"><thead><tr><th>#</th><th>Equipo</th>${['JJ','JG','JP','PF','PC','Dif','Pts'].map(s=>'<th>'+s+'</th>').join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr class="${i<d.qualify?'qualifies':''}"><td>${i+1}${r.tied?' *':''}</td><td>${H(r.name)}</td><td>${r.played}</td><td>${r.won}</td><td>${r.lost}</td><td>${r.pf}</td><td>${r.pc}</td><td>${r.pf-r.pc}</td><td>${r.points}</td></tr>`).join('')}</tbody></table></div>${rows.some(r=>r.tied)?'<p>* Empate exacto: orden provisional.</p>':''}</div>`;}).join('')||'<p class="tor-empty">Todavía no hay grupos.</p>'}`;}
 function gameCard(g,capture=false){const t=tournament,d=div();const sideLabel=s=>g[s]?entryName(g[s]):g[s+'Source']?'Ganador de '+C.roundName(t,t.games.find(x=>x.id===g[s+'Source']))+' · '+(1+t.games.filter(x=>x.divisionId===g.divisionId&&x.round===t.games.find(x=>x.id===g[s+'Source']).round&&x.phase==='knockout').findIndex(x=>x.id===g[s+'Source'])) : 'Por definir';return `<article class="tor-card"><span class="tor-tag">${g.phase==='groups'?H(d.groups.find(x=>x.id===g.groupId)?.name):H(C.roundName(t,g))}</span><h3>${H(sideLabel('home'))} ${g.bye?'— Pase libre':'vs '+H(sideLabel('away'))}</h3><div class="tor-score">${g.bye?'Avanza sin jugar':g.status==='jugado'?g.homeScore+' – '+g.awayScore:H(g.status)}</div><p>${H(g.date||'Fecha por definir')} ${H(g.time)} · ${H(t.venues.find(v=>v.id===g.venueId)?.name??'Cancha por definir')}</p>${g.status==='jugado'&&!g.bye?`<p>${g.statsComplete?'Estadísticas completas':'Estadísticas pendientes'}</p>${action('sheet','Ver hoja de estadísticas',g.id,'secondary')}`:''}${admin&&!g.bye?`<div class="tor-actions">${action('game-edit','Editar horario',g.id,'secondary')}${g.home&&g.away&&g.status!=='cancelado'?action('result',g.status==='jugado'?'Corregir resultado':'Capturar resultado',g.id):''}${g.phase==='groups'?action('game-cancel',g.status==='cancelado'?'Reactivar':'Cancelar',g.id,'secondary'):''}${g.status==='jugado'?action('reopen','Reabrir resultado',g.id,'secondary'):''}${g.phase==='groups'?action('game-delete','Eliminar',g.id,'danger'):''}</div>`:''}</article>`;}
 function renderGames(capture){if(!div())return '<p>Elige una categoría.</p>';const games=tournament.games.filter(g=>g.divisionId===divisionId&&!g.bye).sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')||(a.time||'').localeCompare(b.time||''));return `<h2>${capture?'Capturar resultados':'Rol de juegos'}</h2>${admin&&!capture?`<div class="tor-actions">${action('generate','Generar todos contra todos')}${action('game-new','Agregar Juego','','secondary')}${action('clear-groups','Retirar rol de grupos','','danger')}</div>`:''}${preview?.kind==='schedule'?`<div class="tor-preview"><h3>Vista previa: ${preview.games.length} partidos</h3><p>Revisa fechas, canchas y descansos antes de aplicar al torneo.</p>${action('accept-schedule','Aplicar este rol')}${action('discard-preview','Descartar vista previa','','secondary')}${preview.games.map(g=>`<p>${H(g.date)} ${g.time} · ${H(entryName(g.home))} vs ${H(entryName(g.away))} · ${H(tournament.venues.find(v=>v.id===g.venueId)?.name)}</p>`).join('')}</div>`:''}<div class="tor-grid">${games.map(g=>gameCard(g,capture)).join('')||'<p class="tor-empty">Todavía no hay partidos. Genera el rol o agrega uno.</p>'}</div>`;}
 function renderBracket(){if(!div())return '<p>Elige una categoría.</p>';const games=tournament.games.filter(g=>g.divisionId===divisionId&&g.phase==='knockout');const shown=preview?.kind==='bracket'?preview.games:games;const temp={...tournament,games:[...tournament.games.filter(g=>g.divisionId!==divisionId||g.phase!=='knockout'),...shown]};return `<h2>Eliminatorias a un partido</h2><p>Cuartos, semifinales y final según el número de clasificados. Cada ganador avanza; los pases libres no suman estadísticas.</p>${admin?`<div class="tor-actions">${action('bracket','Preparar clasificados y cruces')}${games.length?action('clear-bracket','Retirar llave y revisar grupos','','danger'):''}</div>`:''}${preview?.kind==='bracket'?`<div class="tor-preview"><h3>Vista previa de cruces</h3><p>${shown.filter(g=>g.bye).length} pases libres. Revisa los cruces antes de confirmar.</p>${action('accept-bracket','Confirmar esta llave')}${action('discard-preview','Descartar','','secondary')}</div>`:''}<div class="tor-bracket">${[...new Set(shown.map(g=>g.round))].map(r=>`<section class="tor-round"><h3>${H(C.roundName(temp,shown.find(g=>g.round===r)))}</h3>${shown.filter(g=>g.round===r).map(g=>preview?.kind==='bracket'?`<div class="tor-card">${g.home?H(entryName(g.home)):'Ganador anterior'} ${g.bye?'— Pase libre':'vs '+(g.away?H(entryName(g.away)):'Ganador anterior')}</div>`:gameCard(g)).join('')}</section>`).join('')||'<p class="tor-empty">Completa los grupos para confirmar sus clasificados y generar la llave.</p>'}</div>`;}
 function renderLeaders(){if(!div())return '<p>Elige una categoría.</p>';return `<h2>Líderes y rankings</h2><div class="tor-row">${select('Etapa','stats-phase',[{id:'',name:'Todo el torneo'},{id:'groups',name:'Grupos'},{id:'knockout',name:'Eliminatorias'}],'','id="stats-phase"')}${select('Grupo','stats-group',[{id:'',name:'Todos los grupos'},...div().groups],'','id="stats-group"')}</div><div id="stats-result">${statsHTML('','')}</div>`;}
 function statsHTML(phase,groupId){const s=C.stats(tournament,divisionId,{phase,groupId});const players=[...s.players].sort((a,b)=>b.points-a.points);const rank=(label,field,ascending=false)=>`<h3>${label}</h3><ol>${[...s.teams].sort((a,b)=>ascending?a[field]/a.played-b[field]/b.played:b[field]/b.played-a[field]/a.played).map(e=>`<li>${H(e.name)} · ${(e[field]/e.played).toFixed(1)} por juego</li>`).join('')}</ol>`;return `<p>${s.games.length} partidos terminados. ${s.games.filter(g=>!g.statsComplete&&g.forfeit==='ninguno').length} con estadísticas pendientes.</p><div class="tor-scroll"><table class="tor-table"><thead><tr>${['Jugador','Equipo','JJ','Pts','3pt','Faltas','Pts/J','3pt/J','MVP'].map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${players.map(p=>`<tr><td>${action('player',H(p.name),p.id,'secondary tor-profile')}</td><td>${H(p.team)}</td><td>${p.played}</td><td>${p.points}</td><td>${p.threes}</td><td>${p.fouls}</td><td>${(p.points/p.played).toFixed(1)}</td><td>${(p.threes/p.played).toFixed(1)}</td><td>${p.mvp}</td></tr>`).join('')}</tbody></table></div><div class="tor-grid">${[['Puntos','points'],['Triples','threes'],['Faltas','fouls'],['Más veces MVP','mvp']].map(([title,field])=>`<div class="tor-card"><h3>${title}</h3><ol>${[...s.players].sort((a,b)=>b[field]-a[field]).slice(0,10).map(p=>`<li>${H(p.name)} · ${H(p.team)}: ${p[field]}</li>`).join('')}</ol></div>`).join('')}</div><div class="tor-grid">${[['Más ofensivos','pf',false],['Más defensivos','pc',true],['Más tripleros','threes',false],['Defensa de triples','againstThrees',true],['Fair play','fouls',true]].map(args=>'<div class="tor-card">'+rank(...args)+'</div>').join('')}</div><p class="tor-muted">Los promedios usan participaciones registradas. Puedes comparar grupos o eliminatorias por separado; los finalistas juegan más partidos.</p>`;}
 function renderSettings(){return `<h2>Configuración</h2><div class="tor-actions">${action('settings','Nombre, logo, fechas y estado')}${action('division-new','Crear categoría y rama')}${action('venues','Administrar canchas')}${action('duplicate','Duplicar como otro torneo','','secondary')}${action('trash','Papelera y restauración','','secondary')}</div><div class="tor-grid">${tournament.divisions.map(d=>`<div class="tor-card"><h3>${H(d.name)} · ${H(d.branch)}</h3><p>${d.groups.length} grupos · ${d.qualify} clasificados por grupo</p>${action('division-edit','Editar categoría / reglas',d.id,'secondary')}${action('division-delete','Eliminar categoría',d.id,'danger')}</div>`).join('')}</div><details><summary>Historial reciente de cambios</summary>${[...(tournament.history??[])].reverse().map(h=>'<p>'+H(h.at)+' · '+H(h.action)+'</p>').join('')}</details><p class="tor-muted">Borrador y Archivado se ocultan del listado público. Los archivos del repositorio siguen siendo públicos. Guarda los cambios para publicarlos.</p>`;}
 function renderCompare(){const es=C.divisionEntries(tournament,divisionId).map(e=>({id:e.id,name:entryName(e.id)}));return '<h2>Comparar equipos de esta categoría</h2><div class="tor-row">'+select('Primer equipo','compare-a',[{id:'',name:'Elige equipo'},...es],'','id="compare-a"')+select('Segundo equipo','compare-b',[{id:'',name:'Elige equipo'},...es],'','id="compare-b"')+'</div><div id="compare-result"></div>';}
 function compareResult(){const a=$('compare-a').value,b=$('compare-b').value;if(!a||!b)return;if(a===b){$('compare-result').textContent='Elige dos equipos diferentes.';return;}const s=C.stats(tournament,divisionId),left=s.teams.find(e=>e.entryId===a),right=s.teams.find(e=>e.entryId===b);const metrics=[['JJ','played'],['Ganados','won'],['Puntos a favor','pf'],['Puntos recibidos','pc'],['Triples','threes'],['Faltas','fouls']];$('compare-result').innerHTML='<table class="tor-table"><thead><tr><th>Dato</th><th>'+H(entryName(a))+'</th><th>'+H(entryName(b))+'</th></tr></thead><tbody>'+metrics.map(([name,k])=>'<tr><th>'+name+'</th><td>'+(left?.[k]??0)+'</td><td>'+(right?.[k]??0)+'</td></tr>').join('')+'</tbody></table><h3>Enfrentamientos en este torneo</h3>'+s.games.filter(g=>[g.home,g.away].includes(a)&&[g.home,g.away].includes(b)).map(g=>gameCard(g)).join('');}
 function settings(isNew=false){const t=isNew?C.create('Nuevo torneo'):tournament;modal(isNew?'Crear torneo':'Datos del torneo',field('Nombre del torneo','name',isNew?'':t.name,'text','required maxlength="100"')+imageInput()+`<div class="tor-row">${field('Primer día','start',t.start,'date')}${field('Último día','end',t.end,'date')}</div>`+field('Zona horaria','timezone',t.timezone)+select('Estado','status',[{id:'borrador',name:'Borrador'},{id:'publicado',name:'Publicado'},{id:'finalizado',name:'Finalizado'},{id:'archivado',name:'Archivado'}],t.status),async f=>{const n=C.clone(t);n.name=C.name(f.get('name'));n.start=f.get('start');n.end=f.get('end');n.timezone=f.get('timezone');n.status=f.get('status');const image=await prepareLogo(f.get('logoFile'),n.id);if(image)n.logo=image.path;C.validate(n);if(isNew){sha=null;pendingImages={};divisionId='';view='config';}keepLogo(image,n);commit(n,isNew?'Torneo creado':'Datos del torneo actualizados');});}
 function editDivision(id){const current=tournament.divisions.find(d=>d.id===id)??C.division('Nueva categoría','Varonil');modal(id?'Editar categoría y rama':'Crear categoría y rama',field('Nombre de categoría','name',id?current.name:'','text','required placeholder="Libre, Sub-18, 40+…"')+field('Rama','branch',current.branch,'text','required list="branch-options"')+'<datalist id="branch-options"><option value="Varonil"><option value="Femenil"><option value="Mixta"></datalist>'+select('Clasifican por grupo','qualify',[{id:'1',name:'Uno'},{id:'2',name:'Dos'}],String(current.qualify))+`<div class="tor-row">${field('Puntos por victoria','win',current.win,'number','min="0" required')}${field('Puntos por derrota','loss',current.loss,'number','min="0" required')}${field('Puntos por forfeit','forfeit',current.forfeit,'number','min="0" required')}</div><p>Todos contra todos en grupos y eliminatorias a un solo partido.</p>`,f=>{const n=C.clone(tournament),d=C.clone(current);d.name=C.name(f.get('name'));d.branch=C.name(f.get('branch'));for(const k of ['qualify','win','loss','forfeit'])d[k]=C.integer(f.get(k),k);if(n.divisions.some(x=>x.id!==id&&x.name.toLowerCase()===d.name.toLowerCase()&&x.branch.toLowerCase()===d.branch.toLowerCase()))throw new Error('Ya existe esa categoría y rama.');if(n.games.some(g=>g.divisionId===id&&g.phase==='knockout')&&['qualify','win','loss','forfeit'].some(k=>d[k]!==current[k]))throw new Error('Retira la llave antes de cambiar reglas de clasificación.');n.divisions=n.divisions.filter(x=>x.id!==d.id);n.divisions.push(d);divisionId=d.id;commit(n,'Categoría y rama guardadas');});}
 function editTeam(id){if(!divisionId&&!id)throw new Error('Crea una categoría y rama primero.');const original=tournament.teams.find(t=>t.id===id)??{id:C.id('team'),name:'',logo:''};modal(id?'Editar nombre y logo':'Crear equipo',field('Nombre del equipo','name',original.name,'text','required maxlength="100"')+imageInput()+'<p>El nombre y logo se comparten entre las categorías de este torneo. Cada inscripción tiene su propio roster.</p>',async f=>{const n=C.clone(tournament),team={...original,name:C.name(f.get('name'))};if(n.teams.some(x=>x.id!==team.id&&x.name.toLocaleLowerCase()===team.name.toLocaleLowerCase()))throw new Error('Ese equipo ya existe. Usa Inscribir equipo en esta categoría.');const image=await prepareLogo(f.get('logoFile'),n.id);if(image)team.logo=image.path;n.teams=n.teams.filter(x=>x.id!==team.id);n.teams.push(team);if(!id&&!n.entries.some(e=>e.teamId===team.id&&e.divisionId===divisionId))n.entries.push({id:C.id('entry'),teamId:team.id,divisionId,groupId:'',roster:[]});C.validate(n);keepLogo(image,team);commit(n,id?'Nombre y logo actualizados':'Equipo creado e inscrito');});}
 function enroll(){if(!div())throw new Error('Crea una categoría primero.');const available=tournament.teams.filter(t=>!tournament.entries.some(e=>e.teamId===t.id&&e.divisionId===divisionId));if(!available.length)throw new Error('No hay equipos adicionales. Crea uno o copia desde la liga.');modal('Inscribir equipo en '+div().name,select('Equipo del torneo','team',available)+select('Copiar roster de otra inscripción (opcional)','source',[{id:'',name:'Comenzar con roster vacío'},...tournament.entries.map(e=>({id:e.id,name:entryName(e.id)+' · '+tournament.divisions.find(d=>d.id===e.divisionId).name}))]),f=>{const n=C.clone(tournament);const source=n.entries.find(e=>e.id===f.get('source'));n.entries.push({id:C.id('entry'),teamId:f.get('team'),divisionId,groupId:'',roster:(source?.roster??[]).filter(p=>p.active!==false).map(p=>({...p,id:C.id('player')}))});commit(n,'Equipo inscrito en la categoría');});}
 async function importLeague(){if(!div())throw new Error('Crea una categoría primero.');notify('Cargando equipos y jugadores de la liga…');const [eq,ro,cat,temp]=await Promise.all([store.read('data/equipos.json'),store.read('data/roster.json'),store.read('data/categorias.json'),store.read('data/temporadas.json')]);modal('Copiar un equipo de la liga',select('Equipo','team',eq.data.equipos.map(x=>({id:x.id,name:x.nombre})))+select('Categoría de origen','cat',cat.data.map(x=>({id:x.id,name:x.nombre})))+select('Temporada de origen','season',temp.data.temporadas.map(x=>({id:x.id,name:x.nombre})))+'<p>Solo se copiarán los datos elegidos. La liga no se modifica.</p>',f=>{const original=eq.data.equipos.find(e=>e.id===f.get('team'));const players=ro.data.jugadores.filter(p=>(p.membresias??[]).some(m=>m.equipo_id===original.id&&m.categoria_id===f.get('cat')&&m.temporada===f.get('season')));setTimeout(()=>modal('Elegir jugadores de '+original.nombre,`<p>${players.length} jugadores disponibles. Puedes registrar más después.</p><div class="tor-form-list">${players.map((p,i)=>`<label><input type="checkbox" name="p${i}" checked>${H(p.nombre)} · #${H(p.numero)}</label>`).join('')}</div>`,selected=>{const n=C.clone(tournament);let team=n.teams.find(e=>e.originLeague===original.id||e.name.toLocaleLowerCase()===original.nombre.toLocaleLowerCase());if(!team){team={id:C.id('team'),name:original.nombre,logo:original.logo,originLeague:original.id};n.teams.push(team);}if(n.entries.some(e=>e.teamId===team.id&&e.divisionId===divisionId))throw new Error('Este equipo ya está inscrito en la categoría.');n.entries.push({id:C.id('entry'),teamId:team.id,divisionId,groupId:'',roster:players.filter((p,i)=>selected.has('p'+i)).map(p=>({id:C.id('player'),name:p.nombre,number:String(p.numero??''),originLeague:p.id,active:true}))});commit(n,'Equipo y jugadores copiados desde la liga');}),0);});}
 function roster(eid){const e=tournament.entries.find(e=>e.id===eid),stats=C.stats(tournament,e.divisionId).players;if(!e)throw new Error('Inscripción no encontrada.');const rows=e.roster.map((p,i)=>{const s=stats.find(s=>s.id===p.id);return `<tr><td>${admin?`<input name="name${i}" value="${H(p.name)}" required style="width:200px" aria-label="Nombre jugador ${i+1}">`:H(p.name)}</td><td>${admin?`<input name="number${i}" value="${H(p.number)}" aria-label="Número jugador ${i+1}">`:H(p.number)}</td><td>${admin?`<input type="checkbox" name="active${i}" ${p.active!==false?'checked':''} aria-label="Activo jugador ${i+1}">`:p.active!==false?'Sí':'Baja'}</td><td>${s?.played??0}</td><td>${s?.points??0}</td><td>${s?.threes??0}</td><td>${s?.fouls??0}</td></tr>`;}).join('');modal('Roster de '+entryName(eid),`<div class="tor-scroll"><table class="tor-table"><thead><tr><th>Jugador</th><th>Número</th><th>Activo</th><th>JJ</th><th>Pts</th><th>3pt</th><th>Faltas</th></tr></thead><tbody>${rows}</tbody></table></div>${admin?'<label>Agregar jugadores (uno por línea: Nombre | Número)<textarea name="newPlayers" rows="5" placeholder="Juan Pérez | 12\nLuis García | 8"></textarea></label><p>Desmarcar Activo da de baja al jugador sin borrar su historial.</p>':''}`,f=>{const n=C.clone(tournament),entry=n.entries.find(x=>x.id===eid);entry.roster.forEach((p,i)=>{p.name=C.name(f.get('name'+i));p.number=String(f.get('number'+i)).trim().slice(0,10);p.active=f.has('active'+i);});for(const line of String(f.get('newPlayers')??'').split('\n').filter(l=>l.trim())){const [pname,num='']=line.split('|');const pnameClean=C.name(pname);if(entry.roster.some(p=>p.name.toLocaleLowerCase()===pnameClean.toLocaleLowerCase()))throw new Error('Ya existe '+pnameClean+' en este roster.');entry.roster.push({id:C.id('player'),name:pnameClean,number:num.trim().slice(0,10),active:true});}commit(n,'Roster actualizado');},!admin);}
 function groups(count){const d=div();if(!d)throw new Error('Crea una categoría primero.');if(tournament.games.some(g=>g.divisionId===d.id))throw new Error('Retira el rol y la llave antes de cambiar la composición de grupos.');const entries=C.divisionEntries(tournament,d.id);if(!entries.length)throw new Error('Inscribe equipos primero.');const size=count??(d.groups.length||Math.max(1,Math.ceil(entries.length/4)));const gs=Array.from({length:size},(_,i)=>d.groups[i]??{id:C.id('group'),name:'Grupo '+String.fromCharCode(65+i)});modal('Organizar grupos',field('Número de grupos','count',size,'number','min="1" max="32"')+action('groups-propose','Proponer distribución','','secondary')+gs.map((g,i)=>field('Nombre de grupo '+(i+1),'group'+i,g.name)).join('')+entries.map((e,i)=>select(entryName(e.id),'entry'+e.id,gs,e.groupId&&gs.some(g=>g.id===e.groupId)?e.groupId:gs[i%gs.length].id)).join('')+'<p>Para generar el rol, cada grupo debe tener de 3 a 6 equipos.</p>',f=>{const n=C.clone(tournament),nd=n.divisions.find(x=>x.id===d.id);nd.groups=gs.map((g,i)=>({...g,name:C.name(f.get('group'+i))}));nd.tieOrder=[];for(const e of n.entries.filter(e=>e.divisionId===d.id))e.groupId=f.get('entry'+e.id);commit(n,'Grupos organizados');});}
 function ties(){const d=div(),entries=C.divisionEntries(tournament,d.id);modal('Resolver empates exactos','<p>Usa números únicos: 1 primero, 2 después, etc. Solo se aplica cuando todos los criterios deportivos empatan.</p>'+entries.map((e,i)=>field(entryName(e.id),'rank'+e.id,(d.tieOrder??[]).includes(e.id)?d.tieOrder.indexOf(e.id)+1:i+1,'number','min="1" required')).join('')+field('Motivo de la resolución','reason','','text','required'),f=>{if(tournament.games.some(g=>g.divisionId===d.id&&g.phase==='knockout'))throw new Error('Retira primero la llave para modificar la clasificación.');const n=C.clone(tournament),r=entries.map(e=>({id:e.id,n:C.integer(f.get('rank'+e.id),'Orden',1)}));if(new Set(r.map(x=>x.n)).size!==r.length)throw new Error('Los números de orden deben ser distintos.');n.divisions.find(x=>x.id===d.id).tieOrder=r.sort((a,b)=>a.n-b.n).map(x=>x.id);commit(n,'Desempate registrado: '+C.name(f.get('reason')));});}
 function venues(){modal('Canchas del torneo',tournament.venues.map((v,i)=>field('Cancha '+(i+1),'venue'+i,v.name)).join('')+'<label>Agregar canchas (una por línea)<textarea name="newVenues" rows="4"></textarea></label>',f=>{const n=C.clone(tournament);n.venues.forEach((v,i)=>v.name=C.name(f.get('venue'+i)));for(const line of String(f.get('newVenues')??'').split('\n').filter(x=>x.trim()))n.venues.push({id:C.id('venue'),name:C.name(line)});commit(n,'Canchas actualizadas');});}
 function generate(){const games=C.groupGames(tournament,divisionId);if(!tournament.venues.length)throw new Error('Agrega las canchas en Configuración primero.');modal('Generar rol — '+games.length+' partidos',`<div class="tor-row">${field('Fecha inicial','start',tournament.start,'date','required')}${field('Fecha final','end',tournament.end||tournament.start,'date','required')}${field('Desde','from','09:00','time','required')}${field('Hasta','to','21:00','time','required')}${field('Minutos estimados por juego','duration',50,'number','min="1" required')}${field('Intervalo entre juegos','gap',10,'number','min="0" required')}${field('Descanso mínimo por equipo (minutos)','rest',60,'number','min="0" required')}</div><p>Canchas disponibles:</p>${tournament.venues.map(v=>`<label class="tor-check"><input type="checkbox" name="venue" value="${H(v.id)}" checked>${H(v.name)}</label>`).join('')}<p>El generador respeta el descanso de cada inscripción y la ocupación de canchas de este torneo. Los horarios son estimados; puedes reprogramarlos.</p>`,f=>{const planned=C.schedule(tournament,games,{...Object.fromEntries(f),venues:f.getAll('venue')});preview={kind:'schedule',games:planned};view='rol';render();notify('Vista previa preparada. Revisa y pulsa Aplicar este rol.');});}
 function editGame(gid){const current=tournament.games.find(g=>g.id===gid);if(!div())throw new Error('Elige una categoría.');if(current?.bye)throw new Error('Un pase libre no necesita horario.');const g=current??{id:C.id('game'),divisionId,groupId:div().groups[0]?.id??'',phase:'groups',round:1,status:'programado',homeScore:0,awayScore:0,homeStats:[],awayStats:[],forfeit:'ninguno',statsComplete:false};const entries=C.divisionEntries(tournament,divisionId).map(e=>({id:e.id,name:entryName(e.id)}));modal(current?'Editar horario del partido':'Agregar Juego',(!current?select('Grupo','group',div().groups,g.groupId)+select('Local','home',entries,g.home)+select('Visitante','away',entries,g.away):'<p>'+H(entryName(g.home))+' vs '+H(entryName(g.away))+'</p>')+`<div class="tor-row">${field('Fecha','date',g.date??'','date','required')}${field('Hora','time',g.time??'','time','required')}${select('Cancha','venue',tournament.venues,g.venueId)}${field('Duración estimada (minutos)','duration',g.duration??50,'number','min="1" required')}</div>`,f=>{const n=C.clone(tournament),ng={...g,date:f.get('date'),time:f.get('time'),venueId:f.get('venue'),duration:C.integer(f.get('duration'),'Duración',1,300)};if(!current){ng.home=f.get('home');ng.away=f.get('away');ng.groupId=f.get('group');if(n.games.some(x=>x.divisionId===divisionId&&x.phase==='knockout'))throw new Error('Retira la llave antes de agregar juegos de grupo.');if(n.games.some(x=>x.divisionId===divisionId&&x.phase==='groups'&&[x.home,x.away].sort().join() === [ng.home,ng.away].sort().join()))throw new Error('Ese cruce ya existe en el rol.');}
   if(n.start&&ng.date<n.start||n.end&&ng.date>n.end)throw new Error('La fecha está fuera de los días del torneo. Amplía las fechas en Configuración.');const m=C.minutes(ng.time);if(n.games.some(o=>o.id!==gid&&o.status!=='cancelado'&&!o.bye&&o.date===ng.date&&o.time&&m<C.minutes(o.time)+(o.duration??50)&&m+ng.duration>C.minutes(o.time)&&(o.venueId===ng.venueId||[ng.home,ng.away].filter(Boolean).some(e=>[o.home,o.away].includes(e)))))throw new Error('Ese horario se cruza con otro partido de la cancha o del equipo.');n.games=n.games.filter(x=>x.id!==ng.id);n.games.push(ng);commit(n,'Horario del partido guardado');});}
 function capture(gid){const g=tournament.games.find(g=>g.id===gid);if(!g.home||!g.away)throw new Error('Primero confirma los ganadores de los partidos anteriores.');const lines=side=>{const e=tournament.entries.find(e=>e.id===g[side]);return `<h3>${H(entryName(e.id))}</h3><div class="tor-scroll"><table class="tor-table"><thead><tr><th>Jugó</th><th>Jugador</th><th>Pts</th><th>3pt</th><th>Faltas</th></tr></thead><tbody>${e.roster.filter(p=>p.active!==false||(g[side+'Stats']??[]).some(x=>x.playerId===p.id)).map(p=>{const x=(g[side+'Stats']??[]).find(x=>x.playerId===p.id);return `<tr><td><input name="played_${p.id}" type="checkbox" ${x?'checked':''} aria-label="Jugó ${H(p.name)}"></td><td>${H(p.name)} #${H(p.number)}</td>${['points','threes','fouls'].map(k=>`<td><input name="${k}_${p.id}" type="number" min="0" step="1" value="${x?.[k]??0}" aria-label="${k==='points'?'Puntos':k==='threes'?'Triples':'Faltas'} ${H(p.name)}"></td>`).join('')}</tr>`;}).join('')}</tbody></table></div>`;};const players=[g.home,g.away].flatMap(e=>tournament.entries.find(x=>x.id===e).roster).map(p=>({id:p.id,name:p.name}));modal('Resultado: '+entryName(g.home)+' vs '+entryName(g.away),`<div class="tor-row">${field('Marcador local','homeScore',g.homeScore??0,'number','min="0" required')}${field('Marcador visitante','awayScore',g.awayScore??0,'number','min="0" required')}</div>`+select('Forfeit','forfeit',[{id:'ninguno',name:'No hubo'},{id:'home',name:'Local no se presentó'},{id:'away',name:'Visitante no se presentó'}],g.forfeit??'ninguno')+lines('home')+lines('away')+select('MVP del partido','mvp',[{id:'',name:'Sin seleccionar'},...players],g.mvp??'')+`<label class="tor-check"><input type="checkbox" name="complete" ${g.statsComplete?'checked':''}>Estadísticas completas (la suma debe coincidir con el marcador)</label><p>Puedes guardar el resultado con estadísticas pendientes. Marca Jugó para registrar una participación. Un forfeit queda 20–0 sin estadísticas individuales.</p>`,f=>{const values={homeScore:C.integer(f.get('homeScore'),'Marcador local'),awayScore:C.integer(f.get('awayScore'),'Marcador visitante'),forfeit:f.get('forfeit'),mvp:f.get('mvp'),statsComplete:f.has('complete')};for(const side of ['home','away'])values[side+'Stats']=tournament.entries.find(e=>e.id===g[side]).roster.filter(p=>f.has('played_'+p.id)).map(p=>({playerId:p.id,points:C.integer(f.get('points_'+p.id),'Puntos'),threes:C.integer(f.get('threes_'+p.id),'Triples'),fouls:C.integer(f.get('fouls_'+p.id),'Faltas')}));if(values.forfeit!=='ninguno'){values.homeScore=values.forfeit==='home'?0:20;values.awayScore=values.forfeit==='away'?0:20;values.homeStats=[];values.awayStats=[];values.mvp='';values.statsComplete=true;}commit(C.result(tournament,gid,values),'Resultado y estadísticas actualizados');});}
 function sheet(gid){const g=tournament.games.find(g=>g.id===gid);modal('Hoja de estadísticas',`<h3>${H(entryName(g.home))} ${g.homeScore} – ${g.awayScore} ${H(entryName(g.away))}</h3><p>${H(g.date)} ${H(g.time)} · ${g.statsComplete?'Estadísticas completas':'Estadísticas pendientes'}</p>`+['home','away'].map(side=>`<h3>${H(entryName(g[side]))}</h3><table class="tor-table"><thead><tr><th>Jugador</th><th>Puntos</th><th>Triples</th><th>Faltas</th></tr></thead><tbody>${(g[side+'Stats']??[]).map(x=>{const p=tournament.entries.find(e=>e.id===g[side]).roster.find(p=>p.id===x.playerId);return `<tr><td>${H(p?.name)}${g.mvp===x.playerId?' ★ MVP':''}</td><td>${x.points}</td><td>${x.threes}</td><td>${x.fouls}</td></tr>`;}).join('')}</tbody></table>`).join(''),null,true);}
 function player(pid){const e=tournament.entries.find(e=>e.roster.some(p=>p.id===pid)),p=e?.roster.find(p=>p.id===pid);if(!p)return;const s=C.stats(tournament,e.divisionId).players.find(x=>x.id===pid);modal(p.name,`<p>${H(entryName(e.id))} · #${H(p.number)}</p><p>${s?.played??0} JJ · ${s?.points??0} puntos · ${s?.threes??0} triples · ${s?.fouls??0} faltas · ${s?.mvp??0} MVP</p>`+tournament.games.filter(g=>g.divisionId===e.divisionId&&g.status==='jugado').flatMap(g=>['home','away'].flatMap(side=>(g[side+'Stats']??[]).filter(x=>x.playerId===pid).map(x=>`<p>${H(g.date)} · ${H(entryName(g.home))} ${g.homeScore}–${g.awayScore} ${H(entryName(g.away))}: ${x.points} pts, ${x.threes} triples, ${x.fouls} faltas</p>`))).join(''),null,true);}
 function makeBracket(){const seeds=C.qualifiers(tournament,divisionId);const list=seeds.map(s=>({id:s,name:entryName(s)+' · '+div().groups.find(g=>g.id===tournament.entries.find(e=>e.id===s).groupId)?.name}));modal('Orden de clasificados','<p>Orden inicial por puesto de grupo. Ajusta el orden si el reglamento asigna pases libres de otra manera. La siguiente pantalla muestra los cruces antes de confirmarlos.</p>'+seeds.map((s,i)=>select('Posición '+(i+1),'seed'+i,list,s)).join(''),f=>{const ordered=seeds.map((s,i)=>f.get('seed'+i));preview={kind:'bracket',games:C.bracket(tournament,divisionId,ordered),seeds,order:ordered};view='llaves';render();notify('Revisa los cruces y pases libres; todavía no están confirmados.');});}
 function trash(){modal('Papelera',tournament.trash.map(x=>`<article class="tor-card"><p>${H(x.kind)} · ${H(x.at)}</p>${action('restore','Restaurar',x.id,'secondary')}</article>`).join('')||'<p>La papelera está vacía.</p>',null,true);}
 function archive(n,kind,value){n.trash.push({id:C.id('trash'),kind,value:C.clone(value),at:new Date().toISOString()});}
 async function handle(a,id){
  if(a==='open')return open(id);if(a==='tab'){view=id;render();return;}if(a==='print'){window.print();return;}if(a==='export'){exportJSON();return;}if(a==='sheet')return sheet(id);if(a==='player')return player(id);if(a==='roster')return roster(id);
  if(a==='catalog'){if(dirty&&!confirm('¿Descartar cambios pendientes y volver al listado?'))return;divisionId='';history.replaceState(null,'',admin?'?administrar=1':'./');return refresh();}
  editable();
  if(a==='new')return settings(true);if(a==='settings')return settings();if(a==='save')return save();if(a==='reload'){if(dirty&&!confirm('¿Descartar el borrador y cargar lo guardado?'))return;localStorage.removeItem('lmbc_tor_draft_'+tournament.id);dirty=false;return open(tournament.id);}
  if(a==='division-new')return editDivision();if(a==='division-edit')return editDivision(id);if(a==='team-new')return editTeam();if(a==='team-edit')return editTeam(id);if(a==='entry-new')return enroll();if(a==='import')return importLeague();if(a==='groups')return groups();if(a==='groups-propose'){const count=C.integer(form.elements.count.value,'Grupos',1,32);formDirty=false;return groups(count);}if(a==='ties')return ties();if(a==='venues')return venues();if(a==='generate')return generate();if(a==='game-new')return editGame();if(a==='game-edit')return editGame(id);if(a==='result')return capture(id);if(a==='bracket')return makeBracket();if(a==='trash')return trash();
  if(a==='discard-preview'){preview=null;render();return;}
  if(a==='accept-schedule'){const n=C.clone(tournament);n.games.push(...preview.games);preview=null;commit(n,'Rol de grupos generado');return;}
  if(a==='accept-bracket'){const n=C.clone(tournament),d=n.divisions.find(d=>d.id===divisionId);d.bracketSeeds=preview.seeds;d.bracketOrder=preview.order;n.games.push(...preview.games);preview=null;commit(n,'Llave de eliminación confirmada');return;}
  if(a==='reopen'){const affected=C.descendants(tournament,id).filter(g=>g.status==='jugado');if(confirm('Se reabrirán '+affected.length+' resultados de esta ruta de la llave. Sus capturas se guardarán en Papelera. ¿Continuar?'))commit(C.reopen(tournament,id),'Resultado reabierto');return;}
  if(a==='clear-bracket'||a==='clear-groups'){const phase=a==='clear-bracket'?'knockout':'groups';if(phase==='groups'&&tournament.games.some(g=>g.divisionId===divisionId&&g.phase==='knockout'))throw new Error('Retira primero la llave de eliminatorias.');const selected=tournament.games.filter(g=>g.divisionId===divisionId&&g.phase===phase);if(!selected.length)throw new Error('No hay partidos que retirar.');if(!confirm('Se retirarán '+selected.length+' partidos y sus resultados. Podrás recuperarlos desde Papelera si no hay conflictos. ¿Continuar?'))return;const n=C.clone(tournament);archive(n,'games',{games:selected,divisionId,seeds:div().bracketSeeds??[]});n.games=n.games.filter(g=>!selected.some(x=>x.id===g.id));n.divisions.find(d=>d.id===divisionId).bracketSeeds=[];commit(n,'Partidos retirados a Papelera');return;}
  if(a==='game-delete'||a==='game-cancel'){const g=tournament.games.find(g=>g.id===id);if(tournament.games.some(x=>x.divisionId===g.divisionId&&x.phase==='knockout')&&g.phase==='groups')throw new Error('Retira la llave antes de retirar un partido clasificatorio.');if(g.status==='jugado')throw new Error('Reabre el resultado primero para conservar una copia de sus estadísticas.');if(g.phase==='knockout')throw new Error('Una eliminatoria define el avance. Reprograma el partido o retira la llave completa para cambiarla.');if(!confirm(a==='game-delete'?'¿Eliminar el partido? Se conservará en Papelera.':'¿Cambiar el estado de este partido?'))return;const n=C.clone(tournament),ng=n.games.find(x=>x.id===id);if(a==='game-delete'){archive(n,'game',ng);n.games=n.games.filter(x=>x.id!==id);}else ng.status=ng.status==='cancelado'?'programado':'cancelado';commit(n,'Partido actualizado');return;}
  if(a==='entry-delete'){if(tournament.games.some(g=>g.home===id||g.away===id))throw new Error('Esta inscripción tiene partidos. Retira esos partidos antes de eliminarla.');if(!confirm('¿Retirar esta inscripción? Las otras categorías del equipo se conservan.'))return;const n=C.clone(tournament);archive(n,'entry',n.entries.find(e=>e.id===id));n.entries=n.entries.filter(e=>e.id!==id);commit(n,'Inscripción retirada');return;}
  if(a==='division-delete'){if(tournament.entries.some(e=>e.divisionId===id)||tournament.games.some(g=>g.divisionId===id))throw new Error('Retira sus inscripciones y partidos antes de eliminar la categoría.');if(!confirm('¿Eliminar esta categoría y rama?'))return;const n=C.clone(tournament);archive(n,'division',n.divisions.find(d=>d.id===id));n.divisions=n.divisions.filter(d=>d.id!==id);commit(n,'Categoría eliminada');return;}
  if(a==='restore'){const n=C.clone(tournament),item=n.trash.find(x=>x.id===id);if(item.kind==='entry')n.entries.push(item.value);else if(item.kind==='division')n.divisions.push(item.value);else if(item.kind==='game')n.games.push(item.value);else if(item.kind==='games'){if(n.games.some(g=>item.value.games.some(x=>x.id===g.id||x.divisionId===g.divisionId&&x.phase===g.phase)))throw new Error('Ya hay un rol o una llave en esa división. Retíralo antes de restaurar.');n.games.push(...item.value.games);n.divisions.find(d=>d.id===item.value.divisionId).bracketSeeds=item.value.seeds;}else if(item.kind==='result'){const index=n.games.findIndex(g=>g.id===item.value.id);if(index<0)throw new Error('Restaura primero el partido.');if(n.games[index].status==='jugado')throw new Error('Ya hay un resultado. Reábrelo antes de restaurar.');Object.assign(n.games[index],item.value);C.resolve(n);}n.trash=n.trash.filter(x=>x.id!==id);C.validate(n);commit(n,'Registro restaurado');dialog.close();return;}
  if(a==='duplicate'){modal('Duplicar torneo',field('Nombre del nuevo torneo','name','','text','required'),f=>{const n=C.clone(tournament),old=n.id;n.id=C.id('tor');n.name=C.name(f.get('name'));n.status='borrador';n.start='';n.end='';n.games=[];n.trash=[];n.history=[];n.divisions.forEach(d=>{d.bracketSeeds=[];d.bracketOrder=[];d.tieOrder=[];});sha=null;pendingImages={};commit(n,'Torneo duplicado sin resultados desde '+old);});return;}
  if(a==='drafts'){const drafts=Object.keys(localStorage).filter(k=>k.startsWith('lmbc_tor_draft_')).map(k=>{try{return JSON.parse(localStorage.getItem(k));}catch{return null;}}).filter(Boolean);modal('Borradores de este navegador',drafts.map(x=>'<p>'+H(x.data.name)+' '+action('recover','Recuperar',x.data.id)+'</p>').join('')||'<p>No hay borradores.</p>',null,true);return;}
  if(a==='recover'){const x=JSON.parse(localStorage.getItem('lmbc_tor_draft_'+id));tournament=x.data;sha=x.sha;pendingImages=x.images??{};dirty=true;divisionId=tournament.divisions[0]?.id??'';view='resumen';dialog.close();render();return;}
 }
 document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const a=b.dataset.action;Promise.resolve().then(()=>handle(a,b.dataset.id)).then(async()=>{if(dirty&&storeToken()&&['accept-schedule','accept-bracket','reopen','clear-bracket','clear-groups','game-delete','game-cancel','entry-delete','division-delete','restore'].includes(a))await save();}).catch(err=>notify(err.message,true));});
 app.addEventListener('change',e=>{if(e.target.id==='tor-division'){divisionId=e.target.value;preview=null;render();}if(['stats-phase','stats-group'].includes(e.target.id))$('stats-result').innerHTML=statsHTML($('stats-phase').value,$('stats-group').value);if(['compare-a','compare-b'].includes(e.target.id))compareResult();});
 $('tor-auth').hidden=!admin;$('tor-token').value=admin?storeToken():'';
 $('tor-connect').onclick=async()=>{try{if(dirty&&!confirm('Hay un borrador abierto. Guarda o exporta antes de cambiar el acceso. ¿Continuar y recargar?'))return;localStorage.setItem('lmbc_gh_token',$('tor-token').value.trim());const current=tournament?.id??params.get('id');dirty=false;if(current)await open(current);else await refresh();notify('Acceso conectado.');}catch(e){notify(e.message,true);}};
 $('tor-disconnect').onclick=()=>{if(dirty&&!confirm('El borrador quedará en este navegador. ¿Cerrar acceso?'))return;localStorage.removeItem('lmbc_gh_token');$('tor-token').value='';notify('Acceso cerrado.');};
 (async()=>{try{if(params.get('id'))await open(params.get('id'));else await refresh();}catch(e){app.innerHTML='<p>No se pudo abrir esta vista. <a href="./">Volver a Torneos</a></p>';notify(e.message,true);}})();
})();
